import java.math.BigDecimal;
import java.util.Map;
import java.util.TreeMap;

public final class ClaimSettlement {

    private ClaimSettlement() {
    }

    public static BigDecimal netPayable(BigDecimal approved, BigDecimal deductible) {
        if (approved == null || approved.signum() <= 0) {
            return BigDecimal.ZERO;
        }
        BigDecimal applied = deductible == null || deductible.signum() <= 0 ? BigDecimal.ZERO : deductible;
        BigDecimal net = approved.subtract(applied);
        return net.signum() < 0 ? BigDecimal.ZERO : net;
    }

    public static Map<String, BigDecimal> settleAll(Map<String, BigDecimal> approvedByClaim,
            Map<String, BigDecimal> deductibleByClaim) {
        Map<String, BigDecimal> settled = new TreeMap<>();
        if (approvedByClaim == null) {
            return settled;
        }
        for (Map.Entry<String, BigDecimal> entry : approvedByClaim.entrySet()) {
            if (entry.getKey() == null) {
                continue;
            }
            BigDecimal deductible = deductibleByClaim == null ? null : deductibleByClaim.get(entry.getKey());
            settled.put(entry.getKey(), netPayable(entry.getValue(), deductible));
        }
        return settled;
    }
}
